    path:["antioch","damascus","bethshean","samaria","jerusalem","modein","bethzur","marisa"],
    battles:[{n:"Sack of Jerusalem",c:[35.2345,31.7760],r:"Dan 11:28"},{n:"The Akra garrisoned",c:[35.2340,31.7755],r:"Dan 11:31"}],
